<script>
 import {saveFile,descriptor} from '../local-downloads.js';
 import {onMount} from 'svelte';import {assistantPresets} from '../assistant-presets';import {planningInstruction,defaultOutputFormat} from '../assistant-intent';import {Plus,X,ChevronUp,ChevronDown,Play,FolderOpen,ArrowUpRight,Check,RefreshCw,Square,Sparkles} from 'lucide-svelte';import {studio,current,scope,run,save,refresh,notify,jobs as reloadJobs,asset,clearDrafts,goSettings,importImages,editFor,liveAssets} from '../studio.svelte';import {api,clone,rgb,hex,stored,persist,bytes,isTeam} from '../api';import {money} from '../cost';import ScopePicker from './ScopePicker.svelte';
 let instruction=$state(''),folder=$state(stored('assistant-output','')),recipe=$state(null),requestId=crypto.randomUUID(),submitted=$state(false),plan=$state({summary:"本地调色",steps:[],warnings:[],clarification:null,output:null}),sample=$state(null),split=$state(50),presetName=$state(''),presets=$state([]),op=$state('adjust'),configured=$state(false),usage=$state(null),localReport=$state(null);
 let plannedContext=$state('');let execution=$state('batch'),generationModel=$state('');
 function chooseImage(id){studio.batchScope='selection';studio.selected=studio.selected.includes(id)?studio.selected.filter(x=>x!==id):[...studio.selected,id];}
 const stageName=s=>({queued:'等待处理',preparing:'正在准备图片',waiting:'等待供应商生成',submitting:'正在提交',attention:'需要检查',completed:'已完成',partial:'部分完成',pending:'等待处理',ready:'预处理完成',submitted:'已提交，等待生成',generating:'正在生成',uncertain:'结果待确认，请勿重复提交',generated:'图片已生成',done:'已保存',failed:'失败',cancelled:'已取消'}[s]||s);
 const stageValue=s=>({pending:0,ready:2,generated:4,done:5,failed:0,cancelled:0}[s]);
 const context=()=>JSON.stringify([studio.pid,scope(),instruction,execution,generationModel]);
 function usePreset(p){instruction=p.instruction;recipe=null;submitted=false;requestId=crypto.randomUUID();}
 const templates={adjust:{op:'adjust',exposure:0,contrast:1,saturation:1,temperature:0},rotate:{op:'rotate',degrees:90},flip:{op:'flip',axis:'horizontal'},crop:{op:'crop',x:0,y:0,width:1,height:1},resize:{op:'resize',width:1000,height:1000,fit:'pad',background:[255,255,255]},flatten:{op:'flatten',background:[255,255,255]},blur:{op:'blur',sigma:1},sharpen:{op:'sharpen',sigma:1,threshold:3},denoise:{op:'denoise',strength:3},auto_center:{op:'auto_center',padding:.08},deskew:{op:'deskew',max_degrees:10}};
 const labels={width:'宽度',height:'高度',exposure:'曝光',contrast:'对比度',saturation:'饱和度',temperature:'色温',background:'背景颜色',padding:'边距比例',sigma:'强度',threshold:'阈值',strength:'强度',degrees:'角度',axis:'方向',fit:'适配方式',x:'横向起点',y:'纵向起点',adjust:"调色",rotate:"旋转",flip:"翻转",crop:"裁切",resize:"调整尺寸与补边",flatten:"填充透明背景",blur:"模糊",sharpen:"锐化",denoise:"降噪",auto_center:"主体居中",deskew:"纠正倾斜",max_degrees:"最大校正角度",maxBytes:"最大字节数"};
 $effect(()=>{if(studio.mode==='assistant')api('assistant_key_status').then(v=>configured=v).catch(()=>{});});
 onMount(()=>{api('assistant_presets').then(v=>presets=Object.entries(v).map(([name,plan])=>({name,plan}))).catch(e=>studio.error=e.message);api('assistant_key_status').then(v=>configured=v).catch(()=>{});reloadJobs().catch(()=>{});const timer=setInterval(()=>reloadJobs().catch(()=>{}),5000);return()=>clearInterval(timer);});
 let sampleFingerprint=$state('');
 const sampleContext=()=>JSON.stringify([studio.dataRoot,studio.pid,studio.aid,plan,scope().map(id=>{
  const a=current()?.assets.find(a=>a.id===id);
  return [id,a?.generatedBase,a?.edit,id===studio.aid?studio.draft:a&&editFor(a)];
 })]);
 $effect(()=>{if(sample&&sampleFingerprint!==sampleContext())sample=null;});
 async function choose(){const path=await api('pick_output');if(path){folder=path;persist('assistant-output',path);}return path;}
 async function prepare(){await run("正在生成处理方案",async()=>{recipe=null;const result=await api('hybrid_plan',{projectId:studio.pid,ids:[...scope()],instruction:planningInstruction(instruction)});result.recipe=defaultOutputFormat(instruction,result.recipe);recipe=result;plannedContext=context();if(result.recipe.clarification)studio.error=result.recipe.clarification;});}
 async function start(){if(!recipe||plannedContext!==context()||recipe.recipe.clarification)return;await run("正在启动任务",async()=>{if(!folder)await choose();if(!folder)return;await save(scope());await api('hybrid_start',{projectId:studio.pid,ids:[...scope()],instruction,recipe:{...clone(recipe.recipe),generation:recipe.recipe.generation?{...clone(recipe.recipe.generation),mode:execution,model:generationModel||recipe.recipe.generation.model}:null},outputDir:folder,approved:true,clientRequestId:requestId});submitted=true;studio.processTab='jobs';await reloadJobs();notify("后台任务已启动");});}
 async function parse(){await run("正在生成本地处理方案",async()=>{const r=await api('assistant_plan',{projectId:studio.pid,ids:[...scope()],instruction});plan=r.plan;usage=r;});}
 async function preview(){await run("正在处理样图",async()=>{
  sample=null;await save(scope());
  const context=sampleContext();
  const result=await api('assistant_preview',{projectId:studio.pid,ids:[...scope()],plan:clone(plan)});
  if(context!==sampleContext())throw Error("SAMPLE_STALE: 图片已修改，请重新测试一张。");
  sampleFingerprint=context;sample=result;
 });}
 async function apply(){await run("正在应用处理步骤",async()=>{
  const candidate=sample,context=sampleFingerprint,ids=[...scope()];
  const validate=()=>{if(!candidate||sample!==candidate||context!==sampleContext())throw Error("SAMPLE_STALE: 图片已修改，请重新测试一张。");};
  validate();
  if(plan.output&&!folder)await choose();if(plan.output&&!folder)return;
  validate();
  const sampleId=candidate.sampleId;sample=null;
  localReport=await api('assistant_apply',{sampleId,outputDir:plan.output?folder:null});
  await refresh();clearDrafts(ids);if(asset()&&ids.includes(studio.aid))studio.draft=clone(asset().edit);notify(localReport.status&&localReport.status!=='completed'?`本地处理未全部完成，请查看结果`:"本地处理已完成");
 });}
 function move(i,d){const j=i+d;if(j<0||j>=plan.steps.length)return;[plan.steps[i],plan.steps[j]]=[plan.steps[j],plan.steps[i]];}
</script>
<div class="workflow-panel assistant-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>处理图片</h1><span>{scope().length} {scope().length===1?'张图片':'张图片'}</span></div><div class="assistant-tabs segmented"><button class:active={studio.processTab==='auto'} onclick={()=>studio.processTab='auto'}>自然语言处理</button><button class:active={studio.processTab==='local'} onclick={()=>studio.processTab='local'}>本地处理步骤</button><button class:active={studio.processTab==='jobs'} onclick={()=>studio.processTab='jobs'}>任务列表 <span>{studio.jobs.length}</span></button></div>
{#if studio.processTab!=='jobs'}<ScopePicker/><details><summary>选择处理图片 · 已选 {studio.selected.length} 张</summary><div class="button-row"><button class="line-button" onclick={()=>{studio.batchScope='selection';studio.selected=liveAssets().map(a=>a.id);}}>全选</button><button class="line-button" onclick={()=>{studio.batchScope='selection';studio.selected=[];}}>取消全选</button></div><div class="process-selection">{#each liveAssets() as a}<button class:selected={studio.selected.includes(a.id)} aria-pressed={studio.selected.includes(a.id)} onclick={()=>chooseImage(a.id)}><img src={studio.thumbs[a.id]} alt=""/><span>{a.name}</span></button>{/each}</div></details>{/if}
{#if !scope().length&&studio.processTab!=='jobs'}<div class="empty"><h2>请选择要处理的图片</h2><div class="button-row"><button class="primary" onclick={()=>importImages(false)}>导入图片</button><button class="line-button" onclick={()=>{studio.mode='edit';studio.view='grid';}}>打开图片列表</button></div></div>{:else if studio.processTab==='auto'}<div class="assistant-auto"><div class="assistant-images">{#each scope().slice(0,5) as id}<img src={studio.thumbs[id]} alt="已选择"/>{/each}</div><h2>你想如何处理图片？</h2><div class="field-grid"><label>生成方式<select bind:value={execution}><option value="realtime">实时生成（逐张处理）</option><option value="batch">异步生成（后台批量）</option></select></label><label>生图模型<select bind:value={generationModel}><option value="">自动选择</option>{#each studio.catalog?.models||[] as m}<option value={m.id}>{m.name}</option>{/each}</select></label></div>{#if generationModel.startsWith('GPT-Image')}<p class="hint">Poe 使用主机队列逐张生成，不使用 Google 批量接口。</p>{/if}<div class="assistant-presets" aria-label="常用指令">{#each assistantPresets as p}<button class:active={instruction===p.instruction} onclick={()=>usePreset(p)} disabled={submitted}><b>{p.name}</b><span>{p.detail}</span></button>{/each}</div><textarea aria-label="处理要求" bind:value={instruction} rows="5" placeholder="产品主图，800*800，100kb"></textarea><label>本机保存文件夹<div class="input-action"><input bind:value={folder} placeholder="选择文件夹" aria-label="本机保存文件夹" readonly={isTeam}/><button aria-label="选择本机保存文件夹" onclick={()=>run("正在选择文件夹",choose)}><FolderOpen size={17}/></button></div></label><div class="assistant-start"><span class="hint">先检查处理方案，再开始处理</span><button class="primary" disabled={!configured||!instruction.trim()||!scope().length||!!studio.busy||submitted} onclick={prepare}><Sparkles size={15}/>{submitted?"已提交":"检查处理方案"}</button></div>{#if !configured}<button class="text-button" onclick={()=>goSettings('assistant')}>{isTeam?"请联系主机管理员配置 DeepSeek API":"前往设置配置 DeepSeek API"}<ArrowUpRight size={13}/></button>{/if}{#if recipe&&plannedContext===context()}<div class="recipe-summary"><b>{recipe.recipe.summary}</b><span>{recipe.recipe.generation?(generationModel.startsWith('GPT-Image')?'Poe 生成与本地处理':execution==='realtime'?'实时生成与本地处理':'异步批量生成与本地处理'):"本地处理"}</span><span>{recipe.recipe.output.width} × {recipe.recipe.output.height} · {recipe.recipe.output.format}</span><ol class="recipe-steps">{#each recipe.recipe.before as step}<li>{labels[step.op]||step.op}</li>{/each}{#if recipe.recipe.generation}<li>AI 生成 · {recipe.recipe.generation.resolution}<p>{recipe.recipe.generation.prompt}</p></li>{/if}{#each recipe.recipe.after as step}<li>{labels[step.op]||step.op}</li>{/each}<li>导出 {recipe.recipe.output.format.toUpperCase()} · {recipe.recipe.output.maxBytes?`≤ ${Math.round(recipe.recipe.output.maxBytes/1000)} KB`:"不限制文件大小"}</li></ol>{#if !recipe.recipe.clarification}<button class="primary" disabled={submitted||!!studio.busy} onclick={start}>{recipe.recipe.generation?"确认费用并开始":"开始处理"}</button>{/if}{#each recipe.recipe.warnings||[] as warning}<p>{warning}</p>{/each}</div>{/if}{#if submitted}<button class="line-button" onclick={()=>{submitted=false;requestId=crypto.randomUUID();instruction='';recipe=null;}}>新建任务</button>{/if}</div>
{:else if studio.processTab==='local'}<div class="local-layout"><div class="local-plan"><div class="instruction-row"><textarea aria-label="本地处理要求" bind:value={instruction} placeholder="输入处理要求，或在下方添加步骤。" rows="2"></textarea><button class="line-button" disabled={!configured||!instruction.trim()||!!studio.busy} onclick={parse}>生成方案</button></div>{#if usage}<span class="hint">{usage.usage?.total_tokens||0} 用量单位{usage.cost?` · $${usage.cost.minimumUsd.toFixed(6)}–$${usage.cost.maximumUsd.toFixed(6)}`:''}</span>{/if}<div class="step-add"><select bind:value={op} aria-label="选择操作">{#each Object.keys(templates) as key}<option value={key}>{labels[key]}</option>{/each}</select><button class="line-button" onclick={()=>plan.steps.push(clone(templates[op]))} disabled={plan.steps.length>=20}><Plus size={14}/>添加步骤</button></div><div class="steps">{#each plan.steps as step,i}<div class="step"><div class="step-heading"><b>{i+1}. {labels[step.op]||step.op}</b><div><button aria-label={`Move step ${i+1} up`} disabled={i===0} onclick={()=>move(i,-1)}><ChevronUp size={14}/></button><button aria-label={`Move step ${i+1} down`} disabled={i===plan.steps.length-1} onclick={()=>move(i,1)}><ChevronDown size={14}/></button><button aria-label={`Remove step ${i+1}`} onclick={()=>plan.steps.splice(i,1)}><X size={14}/></button></div></div><div class="field-grid">{#each Object.entries(step).filter(([k])=>k!=='op') as [key,value]}<label>{labels[key]||key.replaceAll('_',' ')}{#if Array.isArray(value)}<input aria-label={`${step.op} ${key}`} type="color" value={hex(value)} onchange={e=>step[key]=rgb(e.target.value)}/>{:else if typeof value==='number'}<input aria-label={`${step.op} ${key}`} type="number" step={['width','height','threshold','degrees'].includes(key)?1:.05} value={value} onchange={e=>step[key]=Number(e.target.value)}/>{:else}<select aria-label={`${step.op} ${key}`} value={value} onchange={e=>step[key]=e.target.value}>{#each key==='axis'?['horizontal','vertical']:['pad','crop'] as option}<option value={option}>{{horizontal:'水平',vertical:'垂直',pad:'补边',crop:'裁切'}[option]||option}</option>{/each}</select>{/if}</label>{/each}</div></div>{/each}</div><label class="checkbox-label"><input type="checkbox" checked={!!plan.output} onchange={e=>plan.output=e.target.checked?{format:'webp',width:1000,height:1000,fit:'pad',maxBytes:500000,background:[255,255,255]}:null}/>处理完成后导出</label>{#if plan.output}<div class="field-grid"><label>图片格式<select bind:value={plan.output.format}><option>webp</option><option>png</option><option>jpeg</option></select></label><label>画面适配方式<select bind:value={plan.output.fit}><option value="pad">补边</option><option value="crop">裁切</option></select></label>{#each ['width','height','maxBytes'] as key}<label>{labels[key]||key}<input type="number" min="1" bind:value={plan.output[key]}/></label>{/each}<label>背景颜色<input type="color" value={hex(plan.output.background)} onchange={e=>plan.output.background=rgb(e.target.value)}/></label></div>{/if}{#if plan.clarification}<p class="inline-error">{plan.clarification}</p>{/if}{#each plan.warnings||[] as warning}<p class="hint">{warning}</p>{/each}<div class="preset-save"><input aria-label="预设名称" placeholder="预设名称" bind:value={presetName}/><button class="line-button" disabled={!presetName.trim()||!!studio.busy} onclick={()=>run("正在保存预设",async()=>{await api('assistant_save_preset',{name:presetName,plan:clone(plan)});presets=Object.entries(await api('assistant_presets')).map(([name,plan])=>({name,plan}));notify("已保存预设");})}>保存预设</button></div>{#if presets.length}<select aria-label="选择本地预设" onchange={e=>{if(e.target.value==='')return;const p=presets[Number(e.target.value)];if(p)plan=clone(p.plan);}}><option value="">选择预设</option>{#each presets as p,i}<option value={i}>{p.name}</option>{/each}</select>{/if}</div><div class="sample-panel"><h3>单图测试</h3><p class="sample-name">{current()?.assets.find(a=>a.id===scope()[0])?.name}</p>{#if sample}<div class="sample-comparison"><img src={`data:image/png;base64,${sample.after}`} alt="处理后的样图"/><div class="compare-before" style:clip-path={`inset(0 ${100-split}% 0 0)`}><img src={`data:image/png;base64,${sample.before}`} alt="原始样图"/></div><div class="compare-line" style:left={`${split}%`}></div><input class="compare-slider" type="range" min="0" max="100" bind:value={split} aria-label="样图对比"/></div>{:else}<img class="sample-original" src={studio.thumbs[scope()[0]]} alt="已选样图"/>{/if}<div class="button-row"><button class="line-button" disabled={!!studio.busy||!scope().length||!plan.steps.length||!!plan.clarification} onclick={preview}>先测试一张</button><button class="primary" disabled={!sample||!!studio.busy} onclick={apply}><Check size={14}/>应用到 {scope().length} 张图片</button></div>{#if localReport}<div class="local-report"><h3>处理结果 · {stageName(localReport.status||'completed')}</h3>{#if localReport.total>localReport.processed}<p>{localReport.total-localReport.processed} 张图片已取消，未开始处理。</p>{/if}{#each localReport.items||localReport.results||[] as item}<div class="local-result"><p>{item.name||current()?.assets.find(a=>a.id===item.assetId)?.name||"图片"} · {stageName(item.status)||"已保存"}</p>{#if item.error}<p class="field-error">{item.error}</p>{/if}{#each item.exports||[] as output}<p>导出 · {output.status==='ok'?"已导出":output.status} · {output.bytes} 字节{#if output.path}<small>{output.path}</small>{/if}</p>{/each}</div>{/each}<button class="text-button" onclick={()=>studio.mode='edit'}>返回编辑<ArrowUpRight size={14}/></button></div>{/if}</div></div>
{:else}<div class="task-list"><div class="section-row"><h3>后台任务</h3><button aria-label="刷新任务" onclick={()=>run("正在刷新任务",reloadJobs)}><RefreshCw size={15}/></button></div>{#each studio.jobs as job}<article class="task"><div class="task-heading"><b>{job.recipe.summary}</b><span class={`job-state ${job.state}`}>{stageName(job.state)}</span></div><p>{job.instruction}</p><div class="task-details"><span>{job.items.filter(i=>i.stage==='done').length} / {job.items.length} 张图片</span><span>{job.estimatedUsd!=null?money(job.estimatedUsd,studio.currency,studio.exchangeRate):''}</span></div>{#if job.error}<p class="inline-error">{job.error}</p>{/if}<details open><summary>逐图进度</summary>{#each job.items as item}<div class="task-item"><span>{item.name}</span><div class="item-progress"><span>{item.retentionStatus==='saved_locally'?'已保存到本机，主机副本已清理':item.retentionStatus==='expired'?'保留期已结束，主机副本已清理':stageName(item.stage)}</span><progress max="5" value={stageValue(item.stage)} aria-label={`${item.name}：${stageName(item.stage)}`}></progress>{#if item.exported&&isTeam}<a href={item.exported} download onclick={e=>{e.preventDefault();saveFile(descriptor(item.exported)).catch(e=>studio.error=e.message);}}>下载图片</a>{/if}</div>{#if item.error}<small>{item.error}</small>{/if}{#each item.warnings||[] as w}<small>{w}</small>{/each}</div>{/each}</details><div class="button-row"><button class="line-button" disabled={!job.items.some(i=>i.exported)} onclick={()=>run("正在打开结果",()=>api('hybrid_open_output',{jobId:job.id}))}><FolderOpen size={14}/>{isTeam?"下载文件":"打开结果文件夹"}</button>{#if !['completed','partial','failed','cancelled'].includes(job.state)}<button class="text-button" onclick={()=>run("正在取消",async()=>{await api('hybrid_cancel',{jobId:job.id});await reloadJobs();})}><Square size={12}/>取消</button>{/if}{#if studio.notices.some(n=>n.id===job.id)}<button class="text-button" title="关闭此任务的完成提醒，不删除图片" onclick={()=>run('关闭提醒',async()=>{await api('hybrid_ack',{jobId:job.id});await reloadJobs();})}>关闭完成提醒</button>{/if}</div></article>{/each}{#if !studio.jobs.length}<div class="empty small"><h2>暂无后台任务</h2></div>{/if}</div>{/if}</div>

